def longestCommonWithPattern(s, t, pattern):
    NEG = -10 ** 9
    n, L = len(t), len(pattern)
    prev = [[0] + [NEG] * L for _ in range(n + 1)]
    for i in range(1, len(s) + 1):
        c = s[i - 1]
        cur = [[0] + [NEG] * L] + [None] * n
        for j in range(1, n + 1):
            up, left = prev[j], cur[j - 1]
            row = [up[k] if up[k] > left[k] else left[k] for k in range(L + 1)]
            if c == t[j - 1]:
                diag = prev[j - 1]
                for k in range(L + 1):
                    if diag[k] + 1 > row[k]:
                        row[k] = diag[k] + 1
                    if k and c == pattern[k - 1] and diag[k - 1] + 1 > row[k]:
                        row[k] = diag[k - 1] + 1
            cur[j] = row
        prev = cur
    best = prev[n][L]
    return best if best >= 0 else -1
